/* make sure to keep these in sync with other constants,
e.g. STAGE_DIMENSION_DEFAULTS in lib/screen-utils.js */

$space: 0.5rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 3.125rem;
$library-filter-bar-height: 2.5rem;

$stage-standard-border-width: 0.0625rem;
$stage-full-screen-border-width: 0.1875rem;
$stage-full-screen-stage-padding: 0.1875rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js` */
$full-size: 1095px;
$full-size-paint: 1249px;

$menu-bar-standard-font-size: 0.75rem;
$menu-bar-large-font-size: 0.875rem;
$menu-bar-button-size: 2rem;

$menu-bar-item-max-width: 12rem;
$ui-primary: hsla(215, 100%, 95%, 1); /* #E5F0FF */
$ui-secondary: hsla(215, 75%, 95%, 1); /* #E9F1FC */
$ui-tertiary: hsla(215, 50%, 90%, 1); /* #D9E3F2 */

$ui-modal-overlay: hsla(215, 100%, 65%, 0.9); /* 90% transparent version of motion-primary */
$ui-alert-overlay: hsla(215, 100%, 65%, 0.4); /* 40% transparent version of motion-primary */

$ui-white: hsla(0, 100%, 100%, 1); /* #FFFFFF */
$ui-white-dim: hsla(0, 100%, 100%, 0.75); /* 25% transparent version of ui-white */
$ui-white-transparent: hsla(0, 100%, 100%, 0.25); /* 25% transparent version of ui-white */
$ui-transparent: hsla(0, 100%, 100%, 0); /* 25% transparent version of ui-white */

$ui-black-transparent: hsla(0, 0%, 0%, 0.15); /* 15% transparent version of black */
$ui-black-transparent-10: hsla(0, 0%, 0%, 0.10); /* 10% transparent version of black */

$ui-black: hsla(0, 0%, 0%, 1); /* #000000 */

$ui-green: hsla(163, 85%, 35%, 1); /* #0DA57A */
$ui-green-2: hsla(163, 85%, 40%, 1); /* #0FBD8C */

$ui-orange: hsla(37, 96%, 55%, 1); /* #FAA51D */
$ui-alert-orange: hsla(32, 100%, 94%, 1); /* #FFF0DF */
$text-primary: hsla(225, 15%, 40%, 1); /* #575E75 */
$text-primary-transparent: hsla(225, 15%, 40%, 0.75);

$motion-primary: hsla(215, 100%, 65%, 1); /* #4C97FF */
$motion-tertiary: hsla(215, 60%, 50%, 1); /* #3373CC */

$looks-secondary: hsla(260, 60%, 60%, 1); /* #855CD6 */
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-tertiary */
$looks-light-transparent: hsla(260, 60%, 60%, 0.15); /* 15% transparent version of looks-tertiary */
$looks-secondary-dark: 	hsla(260, 42%, 51%, 1); /* #714EB6 */

$red-primary: hsla(20, 100%, 55%, 1); /* #FF661A */
$red-tertiary: hsla(20, 100%, 45%, 1); /* #E64D00 */

$sound-primary: hsla(300, 53%, 60%, 1); /* #CF63CF */
$sound-tertiary: hsla(300, 48%, 50%, 1); /* #BD42BD */

$control-primary: hsla(38, 100%, 55%, 1); /* #FFAB19 */

$data-primary: hsla(30, 100%, 55%, 1); /* #FF8C1A */

$pen-primary: hsla(163, 85%, 40%, 1); /* #0FBD8C */
$pen-transparent: hsla(163, 85%, 40%, 0.25); /* #0FBD8C */
$pen-tertiary: hsla(163, 86%, 30%, 1); /* #0B8E69 */

$error-primary: hsla(30, 100%, 55%, 1); /* #FF8C1A */
$error-light: hsla(30, 100%, 70%, 1); /* #FFB366 */
$error-transparent: hsla(30, 100%, 55%, 0.25); /* #FF8C1A */

$extensions-primary: hsla(163, 85%, 40%, 1); /* #0FBD8C */
$extensions-tertiary: hsla(163, 85%, 30%, 1); /* #0B8E69 */
$extensions-transparent: hsla(163, 85%, 40%, 0.35); /* 35% transparent version of extensions-primary */
$extensions-light: hsla(163, 57%, 85%, 1); /* opaque version of extensions-transparent, on white bg */

$membership-blue: hsla(215, 60%, 46%, 1); /* #2F6ABC */
$drop-highlight: hsla(215, 100%, 77%, 1); /* lighter than motion-primary */
/*
    Contains constants for the z-index values of elements that are part of the global stack context.
    In other words, z-index values that are "inside" a component are not added here.
    This prevents conflicts between identical z-index values in different components.
*/

/* Toolbox z-index: 40; set in scratch-blocks */
$z-index-extension-button: 42;
$z-index-stage-indicator: 45;
$z-index-add-button: 46;
$z-index-tooltip: 47; /* tooltips should go over add buttons if they overlap */
$z-index-monitor: 48; /* monitors go over add buttons */
$z-index-stage-question: 49; /* "ask" block text input goes above monitors */

$z-index-card: 480;
$z-index-tooltip-overlay: 481;
$z-index-tooltip: 490;
$z-index-alerts: 490;
$z-index-menu-bar: 491; /* menu-bar should go over monitors, alerts, tooltips and tutorials */
$z-index-loader: 500;
$z-index-modal-overlay: 501;
$z-index-modal: 510;

$z-index-drag-layer: 1000;
/* Block drag z-index: 1000; default 50 is overriden in blocks.css */
$z-index-monitor-dragging: 1010;
$z-index-dragging-sprite: 1020; /* so it is draggable into other panes */

$z-index-stage-color-picker-background: 2000;
$z-index-stage-with-color-picker: 2010;
$z-index-stage-header: 5000;
$z-index-stage-wrapper-overlay: 5000;

/* in most interfaces, the context menu is always on top */
$z-index-context-menu: 10000;
@import "../../css/units.css";
@import "../../css/colors.css";
@import "../../css/z-index.css";

body .card-container-overlay {
    position: fixed;
    pointer-events: none;
    z-index: $z-index-card;
}

body .card-container {
    position:absolute;
    pointer-events: auto;
    z-index: $z-index-card;
    margin: 0.5rem 2rem;
    min-width: 468px;
}

.left-card, .right-card {
    height: 90%;
    position: absolute;
    top: 5%;
    background: $ui-white;
    border: 1px solid $ui-tertiary;
    width: .75rem;
    z-index: 10;
    opacity: 0.9;
    overflow: hidden;
}

.left-card {
    left: -.75rem;
    border-right: 0;
    border-top-left-radius: 0.75rem;
    border-bottom-left-radius: 0.75rem;
}

.right-card {
    right: -.75rem;
    border-left: 0;
    border-top-right-radius: 0.75rem;
    border-bottom-right-radius: 0.75rem;
}

.left-card::after, .right-card::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    height: 2.5rem;
    width: 100%;
    background: $extensions-primary;
}

.left-button, .right-button {
    position: absolute;
    top: 50%;
    margin-top: -15px;
    z-index: 20;
    user-select: none;
    cursor: pointer;
    background: $extensions-primary;
    box-shadow: 0 0 0 4px $extensions-transparent;
    height: 44px;
    width: 44px;
    border-radius: 100%;
    border: none;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: all 0.25s ease;
}

.left-button:hover, .right-button:hover {
    box-shadow: 0 0 0 6px $extensions-transparent;
    transform: scale(1.125);
}

.left-button img, .right-button img{
    width: 1.75rem;
}

.left-button {
    left: -27px;
}

.right-button {
    right: -27px;
}

.card {
    border: 1px solid $ui-tertiary;
    border-radius: 0.75rem;
    display: flex;
    flex-direction: column;
    cursor: move;
    z-index: 20;
    overflow: hidden;
    box-shadow: 0px 5px 25px 5px $ui-black-transparent;
    align-items: center;
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.header-buttons {
    width: 100%;
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    background: $extensions-primary;
    border-bottom: 1px solid $extensions-tertiary;
    font-size: 0.625rem;
    font-weight: bold;
    /* Ensure there is enough padding for the focus outline to become visible on Safari */
    box-sizing: border-box;
    padding: 0 0.77rem;
}

.header-buttons button {
    background: none;
    border: none;
}

.header-buttons-hidden {
    border-bottom: 0px;
}

.header-buttons-right {
    display: flex;
    flex-direction: row;
}

.header-buttons img {
    margin-bottom: 2px;
}

.shrink-expand-button {
    cursor: pointer;
    color: white;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 0.75rem;
}

.shrink-expand-button:hover, .all-button:hover {
    background-color: $ui-black-transparent;
}

.remove-button, .all-button {
    cursor: pointer;
    color: white;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 0.75rem;
}

.remove-button:focus-visible,
.shrink-expand-button:focus-visible,
.all-button:focus-visible {
    outline-offset: -4px;
}

.remove-button:hover, .all-button:hover {
    background-color: $ui-black-transparent;
}

.step-title {
    font-size: 0.9rem;
    margin: 0.9rem;
    text-align: center;
    font-weight: bold;
    color: $text-primary;
}

.step-body {
    width: 100%;
    background: $ui-white;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
    text-align: center;

    /* Min height prevents layout changing when images change */
    min-height: 256px;
}

.step-video {
    height: 256px;
}

.step-image {
    max-width: 450px;
    max-height: 200px;
    object-fit: contain;
    background: #F9F9F9;
    border: 1px solid #ddd;
    border-radius: 0.5rem;
    overflow: hidden;
    margin: 0 0.5rem 0.5rem;
}

.decks, .resources {
    display: flex;
    flex-direction: row;
    justify-content: space-around;
    padding: 0 1rem 0.5rem;
}

.deck, .resource {
    display: flex;
    flex-direction: column;
    margin: 0 8px 8px;
    cursor: pointer;
    border: 1px solid $ui-black-transparent;
    border-radius: 0.25rem;
    overflow: hidden;
}

.deck-image, .resource-image {
    width: 200px;
    height: 100px;
    object-fit: cover;
}

.deck-name, .resource-name {
    color: $looks-secondary;
    font-weight: bold;
    font-size: 0.85rem;
    margin: .625rem 0px;
    text-align: center;
    font-weight: bold;
    text-align: center;
    max-width: 200px;
}

.help-icon {
    height: 1.25rem;
}

.close-icon {
    height: 1.25rem;
    margin: .125rem 0; /* To offset the .25rem difference in icon size */
}

[dir="ltr"] .help-icon {
    margin-right: 0.25rem;
}

[dir="rtl"] .help-icon {
    margin-left: 0.25rem;
}

[dir="ltr"] .close-icon {
    margin-left: 0.25rem;
}

[dir="rtl"] .close-icon {
    margin-right: 0.25rem;
}

.see-all {
    display: flex;
    flex-direction: row;
    justify-content: center;
    width: 100%;
    padding: 0.5rem;
}

.see-all-button {
    cursor: pointer;
    padding: 0.5rem 1rem;
    background-color: $looks-secondary;
    color: white;
    font-weight: bold;
    border-radius: 0.25rem;
    display: flex;
    align-items: center;
    color: $ui-white;
    font-size: .75rem;
    font-weight: bold;
    line-height: 1rem;
    text-align: center;
}

[dir="ltr"] .see-all-button img {
    margin-left: 0.5rem;
}

[dir="rtl"] .see-all-button img {
    margin-right: 0.5rem;
}

.steps-list {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
}

.active-step-pip, .inactiveStepPip {
    width: 0.5rem;
    height: 0.5rem;
    margin: 0 0.25rem;
    border-radius: 100%;
    background: $ui-white-transparent;
}

.active-step-pip {
    background: $ui-white;
    box-shadow: 0px 0px 0px 2px $ui-black-transparent;
}

.hidden {
    display: none;
}
